#!@bash@
# pi-nix launcher. Generated by the pi-nix flake; edit the flake, not this file.
#
# Design goals
# ------------
#  * Run Pi directly in the caller's environment: the user's PATH and every
#    environment variable are inherited, so Pi and its tools can use whatever
#    the user already has (jq, rust, python, cloud CLIs, ...). Only the few
#    binaries pi-nix itself needs are prepended to PATH.
#  * Declarative configuration: `settings.json`, `packages` and `mcp.json` are
#    reconciled from the flake on every launch (see `ownership` in the README
#    for whether Pi's own changes are kept), everything else is preserved.
#  * Self-bootstrapping: the pinned Pi runtime is installed on first use and
#    reused offline afterwards. No manual `npm install` step.
#
# Overrides
# ---------
#   PI_NIX_STATE_DIR        runtime + cache location (default: $XDG_STATE_HOME/pi-nix)
#   PI_NIX_NPM_CACHE        npm cache used for the runtime install
#   PI_NIX_MODE             `run` (default) or `reconcile`
#   PI_NIX_FORCE_RECONCILE  1 to re-run package reconciliation unconditionally
#   PI_NIX_RECONCILE_STRICT 0 to warn instead of aborting when package
#                           reconciliation fails (for example while offline)
#   PI_CODING_AGENT_DIR     Pi config dir (the same variable Pi itself reads)
set -euo pipefail

PI_PACKAGE='@piPackage@'
PI_VERSION='@piVersion@'
SHARE_DIR='@shareDir@'
CONFIG_MODE='@configMode@'
CACERT_BUNDLE='@cacertBundle@'
PI_NIX_DEFAULT_MODE='@defaultMode@'

PI_NIX_MODE="${PI_NIX_MODE:-$PI_NIX_DEFAULT_MODE}"

log() { printf 'pi-nix: %s\n' "$*" >&2; }
die() { log "ERROR: $*"; exit 1; }

case "$PI_NIX_MODE" in
  run|reconcile) ;;
  *) die "PI_NIX_MODE must be 'run' or 'reconcile', got '$PI_NIX_MODE'" ;;
esac

# --- environment ------------------------------------------------------------
# Prepend the store paths pi-nix needs, keep the caller's PATH intact.
export PATH="@binPath@${PATH:+:$PATH}"

# Make the launcher itself (`pi`, `pi-reconcile`) callable from Pi's
# subprocesses (e.g. subagents). The *resolved* directory is used so that a
# profile symlink such as ~/.nix-profile/bin does not get promoted ahead of
# the caller's PATH.
case "${BASH_SOURCE[0]}" in
  */*)
    if SELF=$(readlink -f -- "${BASH_SOURCE[0]}" 2>/dev/null) && [ -n "$SELF" ]; then
      PATH="${SELF%/*}:$PATH"
    fi
    ;;
esac

if [ -z "${HOME:-}" ] && [ -z "${PI_NIX_STATE_DIR:-}" ]; then
  die "HOME is not set (set PI_NIX_STATE_DIR to run without a home directory)"
fi

# Declared environment (from the flake). Variables already present in the
# caller's environment win; the rest are exported for Pi, its tools, and
# every subprocess it spawns.
@envExports@

STATE_DIR="${PI_NIX_STATE_DIR:-${XDG_STATE_HOME:-$HOME/.local/state}/pi-nix}"

case "$CONFIG_MODE" in
  shared)   CONFIG_DIR="${PI_CODING_AGENT_DIR:-${HOME:?pi-nix: HOME is required for configDir=shared}/.pi/agent}" ;;
  isolated) CONFIG_DIR="${PI_CODING_AGENT_DIR:-$STATE_DIR/agent}" ;;
  "~"*)     CONFIG_DIR="${PI_CODING_AGENT_DIR:-${HOME:?pi-nix: HOME is required for ~ paths}${CONFIG_MODE#\~}}" ;;
  *)        CONFIG_DIR="${PI_CODING_AGENT_DIR:-$CONFIG_MODE}" ;;
esac
export PI_CODING_AGENT_DIR="$CONFIG_DIR"

mkdir -p "$STATE_DIR" "$CONFIG_DIR"

# Keep the runtime's npm state inside pi-nix, respect user overrides otherwise.
export npm_config_cache="${PI_NIX_NPM_CACHE:-$STATE_DIR/npm-cache}"
export SSL_CERT_FILE="${SSL_CERT_FILE:-$CACERT_BUNDLE}"
export GIT_SSL_CAINFO="${GIT_SSL_CAINFO:-$SSL_CERT_FILE}"

# Runtimes are namespaced by the pinned version so that several environments
# with different pins coexist instead of reinstalling over each other.
RUNTIME_DIR="$STATE_DIR/runtimes/@runtimeName@"
CLI="$RUNTIME_DIR/node_modules/$PI_PACKAGE/dist/bundle/cli.js"

# --- cross-platform lock ----------------------------------------------------
# Serializes the first-run bootstrap and reconciliation. The lock records its
# owner ("host pid"); a lock whose owner is gone is reclaimed immediately, a
# lock without a readable owner (or from another host) after 15 minutes.
# pi-nix never proceeds without the lock: two concurrent installs into the
# same runtime directory would corrupt it.
LOCK_DIR="$STATE_DIR/.lock"
LOCK_HELD=0
LOCK_TIMEOUT=1200
HOSTNAME_SELF=$(uname -n 2>/dev/null || echo unknown)

lock_is_stale() {
  local owner host pid
  owner=$(cat "$LOCK_DIR/owner" 2>/dev/null || true)
  if [ -n "$owner" ]; then
    host=${owner% *}
    pid=${owner##* }
    if [ "$host" = "$HOSTNAME_SELF" ]; then
      ! kill -0 "$pid" 2>/dev/null
      return
    fi
  fi
  find "$LOCK_DIR" -maxdepth 0 -mmin +15 2>/dev/null | grep -q .
}

acquire_lock() {
  local waited=0
  until mkdir "$LOCK_DIR" 2>/dev/null; do
    if lock_is_stale; then
      log "reclaiming stale lock $LOCK_DIR"
      rm -rf "$LOCK_DIR"
      continue
    fi
    if [ "$waited" -eq 0 ]; then
      log "waiting for another pi-nix process (lock: $LOCK_DIR)"
    fi
    waited=$((waited + 1))
    if [ "$waited" -ge "$LOCK_TIMEOUT" ]; then
      die "timed out waiting for $LOCK_DIR; remove it if no other pi-nix process is running"
    fi
    sleep 1
  done
  LOCK_HELD=1
  printf '%s %s\n' "$HOSTNAME_SELF" "$$" > "$LOCK_DIR/owner"
}
release_lock() {
  if [ "$LOCK_HELD" = "1" ]; then
    rm -rf "$LOCK_DIR" 2>/dev/null || true
    LOCK_HELD=0
  fi
}
trap release_lock EXIT
trap 'exit 130' INT
trap 'exit 143' TERM
trap 'exit 129' HUP

# --- Pi runtime -------------------------------------------------------------
installed_version() {
  node -e '
    try { process.stdout.write(require(process.argv[1]).version); }
    catch { process.exit(1); }
  ' "$1/node_modules/$PI_PACKAGE/package.json" 2>/dev/null
}

# An exact version (optionally with a prerelease tag) rather than an npm range
# or dist-tag.
is_exact_version() {
  [[ $PI_VERSION =~ ^[0-9]+\.[0-9]+\.[0-9]+(-[0-9A-Za-z.-]+)?(\+[0-9A-Za-z.-]+)?$ ]]
}

runtime_ok() { # runtime_ok <dir>
  [ -f "$1/node_modules/$PI_PACKAGE/dist/bundle/cli.js" ] || return 1
  # For an exact version pin, make sure the installed copy is that version.
  if is_exact_version; then
    [ "$(installed_version "$1" || true)" = "${PI_VERSION%%+*}" ] || return 1
  fi
  return 0
}

ensure_runtime() {
  if runtime_ok "$RUNTIME_DIR"; then return 0; fi
  log "installing $PI_PACKAGE@$PI_VERSION (first run / version change; needs network)"
  # Install into a scratch directory and swap it in only when complete, so an
  # interrupted or failed install never leaves a half-populated runtime behind.
  local staging="$RUNTIME_DIR.tmp.$$"
  rm -rf "$RUNTIME_DIR".tmp.*
  mkdir -p "$staging"
  printf '{"name":"pi-nix-runtime","private":true,"dependencies":{"%s":"%s"}}\n' \
    "$PI_PACKAGE" "$PI_VERSION" > "$staging/package.json"
  # All installer chatter goes to stderr: stdout is reserved for Pi itself
  # (--print/--mode json pipelines must stay clean).
  if ! npm install --prefix "$staging" --omit=dev --ignore-scripts \
      --no-audit --no-fund --no-progress --loglevel=error </dev/null >&2; then
    rm -rf "$staging"
    die "npm install of $PI_PACKAGE@$PI_VERSION failed"
  fi
  if ! runtime_ok "$staging"; then
    rm -rf "$staging"
    die "Pi runtime did not install correctly (expected $PI_PACKAGE@$PI_VERSION)"
  fi
  rm -rf "$RUNTIME_DIR"
  mv "$staging" "$RUNTIME_DIR"
}

# --- reconcile declared configuration ---------------------------------------
field() { # field <NAME>: value of NAME=... in $result (empty when absent)
  printf '%s\n' "$result" | sed -n "s/^$1=//p"
}

reconcile_tool() {
  PI_NIX_SHARE_DIR="$SHARE_DIR" PI_NIX_CONFIG_DIR="$CONFIG_DIR" \
    node "$SHARE_DIR/reconcile.mjs" "$@"
}

reconcile() {
  local result force
  force="${PI_NIX_FORCE_RECONCILE:-0}"

  acquire_lock
  ensure_runtime

  result=$(reconcile_tool) || die "configuration reconciliation failed"

  if [ "$(field SETTINGS_CHANGED)" = "1" ]; then log "updated $CONFIG_DIR/settings.json"; fi
  if [ "$(field MCP_CHANGED)" = "1" ]; then log "updated $CONFIG_DIR/mcp.json"; fi

  # Package reconciliation is only needed when the declared set changed (or a
  # previous attempt failed), the npm tree is missing, or the caller asked.
  if [ "$(field PACKAGES_CHANGED)" = "1" ] || [ "$force" = "1" ] \
      || { [ "$(field NPM_PACKAGES)" = "1" ] && [ ! -d "$CONFIG_DIR/npm/node_modules" ]; }; then
    log "reconciling extension packages (needs network for new sources)"
    if node "$CLI" update --extensions --no-approve </dev/null >&2; then
      reconcile_tool --packages-done || die "could not record package state"
    elif [ "${PI_NIX_RECONCILE_STRICT:-1}" = "0" ]; then
      log "WARNING: package reconciliation failed; continuing with the previous package set (will retry next launch)"
    else
      die "package reconciliation failed (set PI_NIX_RECONCILE_STRICT=0 to continue anyway)"
    fi
  fi

  release_lock
}

reconcile

if [ "$PI_NIX_MODE" = "reconcile" ]; then
  log "configuration is up to date"
  exit 0
fi

# --- run --------------------------------------------------------------------
exec node "$CLI" "$@"
